class Solution {
    public int longestSubsequence(int[] arr,int difference){
        Map<Integer,Integer> dp=new HashMap<>();
        int answer=0;
        for(int value:arr){
            int length=dp.getOrDefault(value-difference,0)+1;
            dp.put(value,Math.max(dp.getOrDefault(value,0),length));
            answer=Math.max(answer,length);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun longestSubsequence(arr:IntArray,difference:Int):Int{
        val dp=mutableMapOf<Int,Int>();
        var answer=0;
        for(value in arr){
            val length=(dp[value-difference]?:0)+1;
            dp[value]=maxOf(dp[value]?:0,length);
            answer=maxOf(answer,length)
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int longestSubsequence(vector<int>& arr,int difference){
        unordered_map<int,int> dp;
        int answer=0;
        for(int value:arr){
            int length=dp[value-difference]+1;
            dp[value]=max(dp[value],length);
            answer=max(answer,length);
        }
        return answer;
    }
};
